## Code Example
```typescript
// Pseudo-implementation sketch
type Claims = { tenant:string; scopes:string[]; sub:string }
function normalize(token:string):Claims { /* validate OIDC/SAML and map to internal claims */ }
function loadPolicy(tenant:string, path:string):Policy|undefined { /* TTL cache */ }
function authorize(token:string, path:string):boolean {
  const c = normalize(token);
  const p = loadPolicy(c.tenant, path);
  return p ? c.scopes.includes(p.requiredScope) && c.tenant===p.tenant : false;
}
```

